/**
 * NGAE FOOD PROCESSORS / NGAE BAKERY
 * Centralized Branding Configuration & Document Watermark System
 */
(function() {
    "use strict";

    const NGAE_BRANDING = {
        COMPANY_NAME: "NGAE FOOD PROCESSORS HUB",
        BRAND_NAME: "NGAE BAKERY",
        COMPANY_SLOGAN: "Daily Production & Financial Management System",
        TAGLINE: "Wazalishaji Bora wa Mikate, Maandazi na Bidhaa za Bakery",
        LOGO_PATH: "assets/branding/ngae-bakery-logo.png",
        LOGO_WATERMARK_PATH: "assets/branding/ngae-bakery-logo-watermark.png",
        FAVICON_PATH: "assets/branding/favicon-32x32.png",
        
        PRIMARY_COLOR: "#b91c1c",
        PRIMARY_HOVER: "#991b1b",
        ACCENT_COLOR: "#f59e0b",
        ACCENT_LIGHT: "#fef3c7",
        BORDER_GOLD: "#fbbf24",
        DARK_TEXT: "#0f172a",
        MUTED_TEXT: "#475569",

        PHONE_PRIMARY: "+255 765 394 352",
        PHONE_SECONDARY: "+255 776 637 247",
        FOOTER_TEXT: "Generated from Ngae Food Processing System | Simu: +255 765 394 352 / +255 776 637 247",

        LOGO_DATA_URL: "data:image/png;base64,",

        WATERMARK_DATA_URL: "data:image/png;base64,",

        getWatermarkCss: function() {
            return `
                .ngae-document-container {
                    position: relative;
                    background-color: #ffffff;
                    color: #1e293b;
                    font-family: Tahoma, "Segoe UI", Arial, sans-serif;
                    font-size: 12px;
                    line-height: 1.45;
                }
                .ngae-watermark-overlay {
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    transform: translate(-50%, -50%) rotate(-18deg);
                    width: 440px;
                    max-width: 75%;
                    height: auto;
                    opacity: 0.11;
                    pointer-events: none;
                    user-select: none;
                    z-index: 0;
                }
                @media print {
                    .ngae-watermark-fixed {
                        position: fixed;
                        top: 50%;
                        left: 50%;
                        transform: translate(-50%, -50%) rotate(-18deg);
                        width: 460px;
                        max-width: 80%;
                        height: auto;
                        opacity: 0.11;
                        pointer-events: none;
                        user-select: none;
                        z-index: 0;
                    }
                    .no-print { display: none !important; }
                }
            `;
        },

        getWatermarkHtml: function(isFixed) {
            const cls = isFixed ? "ngae-watermark-fixed" : "ngae-watermark-overlay";
            return `<img src="${this.WATERMARK_DATA_URL}" alt="" class="${cls}" style="position: ${isFixed ? "fixed" : "absolute"}; top: 50%; left: 50%; transform: translate(-50%, -50%) rotate(-18deg); width: 440px; max-width: 75%; opacity: 0.11; pointer-events: none; user-select: none; z-index: 0;">`;
        },

        getHeaderHtml: function(docTitle, docDate, metaRightHtml) {
            const dateStr = docDate || new Date().toLocaleDateString("en-GB");
            return `
                <div class="ngae-doc-header" style="border-bottom: 2.5px solid #b91c1c; padding-bottom: 12px; margin-bottom: 14px; position: relative; z-index: 1;">
                    <table style="width: 100%; border-collapse: collapse;">
                        <tr>
                            <td style="width: 70px; vertical-align: middle;">
                                <img src="${this.LOGO_DATA_URL}" alt="Ngae Bakery" style="width: 62px; height: auto; display: block;">
                            </td>
                            <td style="vertical-align: middle; padding-left: 12px;">
                                <h1 style="margin: 0; font-size: 17px; font-weight: 800; color: #b91c1c; letter-spacing: 0.5px; text-transform: uppercase;">${this.COMPANY_NAME}</h1>
                                <p style="margin: 2px 0 0; font-size: 11px; color: #b45309; font-weight: 700; text-transform: uppercase;">${this.BRAND_NAME} &bull; ${this.COMPANY_SLOGAN}</p>
                            </td>
                            <td style="text-align: right; vertical-align: middle;">
                                <div style="display: inline-block; background: #fef2f2; border: 1.5px solid #fecaca; padding: 6px 12px; border-radius: 6px; text-align: right;">
                                    <span style="display: block; font-size: 10px; color: #b91c1c; font-weight: 800; text-transform: uppercase;">${docTitle || "OFFICIAL REPORT"}</span>
                                    <span style="font-size: 12px; font-weight: 800; color: #0f172a;">${dateStr}</span>
                                </div>
                            </td>
                        </tr>
                    </table>
                    ${metaRightHtml ? `<div style="margin-top: 8px; font-size: 11px; color: #475569;">${metaRightHtml}</div>` : ""}
                </div>
            `;
        },

        getFooterHtml: function() {
            const printTimestamp = new Date().toLocaleString("en-GB");
            return `
                <div class="ngae-doc-footer" style="margin-top: 24px; padding-top: 8px; border-top: 1px solid #cbd5e1; font-size: 10px; color: #64748b; position: relative; z-index: 1;">
                    <table style="width: 100%; border-collapse: collapse;">
                        <tr>
                            <td style="text-align: left;">
                                <strong style="color: #b91c1c;">${this.BRAND_NAME}</strong> &bull; ${this.FOOTER_TEXT}
                            </td>
                            <td style="text-align: right;">
                                Tarehe ya Kuchapishwa: ${printTimestamp}
                            </td>
                        </tr>
                    </table>
                </div>
            `;
        },

        wrapDocumentHtml: function(contentHtml, options) {
            options = options || {};
            const title = options.title || "RIPOTI YA NGAE";
            const date = options.date || "";
            const metaHtml = options.metaHtml || "";
            const maxWidth = options.maxWidth || "780px";

            return `
                <div class="ngae-document-container" style="font-family: Tahoma, \\"Segoe UI\\", Arial, sans-serif; font-size: 12px; color: #1e293b; background: #ffffff; padding: 15px; max-width: ${maxWidth}; margin: 0 auto; line-height: 1.45; position: relative; overflow: hidden;">
                    ${this.getWatermarkHtml(false)}
                    <div style="position: relative; z-index: 1;">
                        ${this.getHeaderHtml(title, date, metaHtml)}
                        <div class="ngae-doc-body" style="position: relative; z-index: 1;">
                            ${contentHtml}
                        </div>
                        ${this.getFooterHtml()}
                    </div>
                </div>
            `;
        }
    };

    window.NGAE_BRANDING = NGAE_BRANDING;

    if (typeof document !== "undefined") {
        const setFavicon = function() {
            let link = document.querySelector("link[rel*=\x27icon\x27]");
            if (!link) {
                link = document.createElement("link");
                link.type = "image/png";
                link.rel = "shortcut icon";
                document.getElementsByTagName("head")[0].appendChild(link);
            }
            link.href = NGAE_BRANDING.FAVICON_PATH;
        };
        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", setFavicon);
        } else {
            setFavicon();
        }
    }
})();